function changeImage(a){var e="";switch(a){case"01":e="./image/mapa-mundi-1.svg";break;case"02":e="./image/mapa-mundi-2.svg";break;case"03":e="./image/mapa-mundi-3.svg";break;case"04":e="./image/mapa-mundi-4.svg";break;case"05":e="./image/mapa-mundi-5.svg";break;case"06":e="./image/mapa-mundi-6.svg";break;default:e="./image/mapa_interativo.png"}document.getElementById("mapaInterativo").src=e}